INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('VIC','Valuer-General Victoria','geojson','free',false,'beta',10,'© State of Victoria, Valuer-General Victoria and Department of Transport and Planning. CC BY 4.0. Boundaries: Vicmap Admin. LandOS code crosswalk and growth calculation.','Annually; controlled import','Area medians are not property valuations. Publisher cautions and carried-forward values are preserved; sales volume is not supplied in this time-series workbook.','vic-suburb-median-prices','Victoria suburb median property prices','Property Market','https://opendata.maps.vic.gov.au/geoserver/wfs','0','https://www.land.vic.gov.au/valuations/resources-and-reports/property-sales-statistics','Original annual suburb/locality house, unit and vacant-land medians. Exact uniquely matched Vicmap bounded localities only; neighbourhoods without a defensible boundary stay unmapped.','{"licence":"Creative Commons Attribution 4.0 International","licence_url":"https://creativecommons.org/licenses/by/4.0/","licence_evidence":"https://discover.data.vic.gov.au/dataset/victorian-property-sales-report-median-house-by-suburb-time-series","verified_on":"2026-10-31","version":"VGV annual suburb workbooks 2015–2025 · Vicmap snapshot 31 October 2026","coverage":"Victoria; uniquely matched official bounded localities only. Unmatched market neighbourhoods remain unavailable.","geography":"Gazetted suburb / bounded locality (Vicmap PFI)","boundary_version":"Vicmap Admin live locality polygons; PFI identity snapshot 31 October 2026","reference_period":"Calendar years 2015–2025; preliminary 2026 excluded","updated":"2026-09-29","methodology":"VGV gazetted neighbourhood/locality sales geography uses LASSI boundaries. A versioned crosswalk maps only exact unique names to Vicmap PFI/VICNAMES IDs; unmatched neighbourhoods are not merged into parent suburbs. Current reference boundaries do not reconstruct historical changes. ^ means fewer than ten sales; * is a previous-year median carried forward because there were zero sales, retained in published fields but treated as missing for the choropleth and growth calculation. Growth compares observed annual medians, not a quality-adjusted index. Sales volume is not supplied. House/unit categories follow VGV classifications and are not universal detached-house/apartment definitions.","fields":["pfi","locality_name","gazetted_locality_name","vicnames_id","house","unit","land","house_source_marker","unit_source_marker","land_source_marker"],"indicators":[{"id":"house","label":"Median house price","unit":"aud","breaks":[400000,600000,800000,1200000,1800000]},{"id":"unit","label":"Median unit price","unit":"aud","breaks":[300000,450000,600000,800000,1100000]},{"id":"land","label":"Median vacant land price","unit":"aud","breaks":[200000,350000,500000,750000,1200000]},{"id":"house_growth","label":"Annual house median change","unit":"percent","breaks":[-5,0,5,10,20]}],"periods":["2025","2024","2023","2022","2021","2020","2019","2018","2017","2016","2015"],"default_indicator":"house","default_period":"2025"}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('VIC','Crime Statistics Agency Victoria','geojson','free',false,'beta',10,'© Crime Statistics Agency Victoria and State of Victoria (Vicmap Admin). CC BY 4.0. LandOS sums of published subgroup counts and explicit locality crosswalk.','Quarterly; rolling annual observations','Counts depend on population, visitors and reporting. Category sums are derived from published subgroups, not adjusted to reconcile with LGA totals.','vic-suburb-recorded-offences','Victoria suburb recorded offences','Crime & Community Safety','https://opendata.maps.vic.gov.au/geoserver/wfs','0','https://discover.data.vic.gov.au/dataset/data-tables-recorded-offences','CSA Table 03 published offence subgroup counts by suburb/town, postcode and LGA. Suburb counts only; no incompatible population denominator or synthetic crime rate.','{"licence":"Creative Commons Attribution 4.0 International","licence_url":"https://creativecommons.org/licenses/by/4.0/","licence_evidence":"https://discover.data.vic.gov.au/dataset/data-tables-recorded-offences","verified_on":"2026-10-31","version":"CSA LGA workbook Table 03 · year ending June 2026 · Vicmap snapshot 31 October 2026","coverage":"Victoria; uniquely matched official bounded localities only. Unmatched market neighbourhoods remain unavailable.","geography":"Gazetted suburb / bounded locality (Vicmap PFI)","boundary_version":"Vicmap Admin live locality polygons; PFI identity snapshot 31 October 2026","reference_period":"Years ending 30 June 2017–2026","updated":"2026-09-24","methodology":"Original Table 03 year/suburb/postcode/LGA/subgroup records are checked for duplicate keys, matched through the explicit unique Vicmap PFI crosswalk and summed across the publisher''s LGA/postcode subdivisions. Counts are sums of published subgroups. CSA confidentiality replaces sensitive homicide/sexual-offence counts of three or less with two when calculating totals. Do not reconcile these derived sums with published LGA totals. Unlisted categories remain missing, not zero. Suburb population rates and residential-only burglary are unavailable at this geography. Current reference boundaries do not reconstruct historical suburb boundaries. Source LGA/postcode labels are retained. NSW crime definitions are separate.","fields":["pfi","locality_name","gazetted_locality_name","vicnames_id","offences","burglary","theft","motor_theft","assault","source_lgas","source_postcodes"],"periods":["2026","2025","2024","2023","2022","2021","2020","2019","2018","2017"],"default_period":"2026","default_indicator":"offences","indicators":[{"id":"offences","label":"Recorded offences · published subgroup sum","unit":"count","breaks":[100,500,1000,2500,5000]},{"id":"burglary","label":"Burglary / break and enter · all locations","unit":"count","breaks":[10,50,100,250,500]},{"id":"theft","label":"Theft","unit":"count","breaks":[50,100,250,500,1000]},{"id":"motor_theft","label":"Motor vehicle theft","unit":"count","breaks":[10,25,50,100,200]},{"id":"assault","label":"Assault and related offences","unit":"count","breaks":[10,25,50,100,250]}]}') ON CONFLICT (id) DO NOTHING;
